<script setup lang="ts">
import {computed,h,ref,watch,onMounted,onUnmounted} from 'vue'
import {NButton,NInput,NSelect,NDataTable,NPagination,NTag,NSwitch,NModal,NForm,NFormItem,NInputNumber,NCheckbox,NSpace,NAlert,useMessage,useDialog} from 'naive-ui'
import type {DataTableColumns} from 'naive-ui'
import {Search,Plus,RefreshCw,Copy,QrCode,Download,Pencil,Link} from '@lucide/vue'
import {state,api,refresh,testLatency,copy,download,pollGeo} from '../store'
import {bytes,protocolNames,nameOf,linksOf,filterNodes,createPreviewGuard} from '../domain'
import type {RelayNode} from '../domain'
import QrDialog from './QrDialog.vue'
import NodeMetrics from './NodeMetrics.vue'
import {FlowCell,LatencyCell,GeoCell} from './LiveCells'
const viewport=ref(window.innerHeight),resized=()=>viewport.value=window.innerHeight;onMounted(()=>window.addEventListener('resize',resized));onUnmounted(()=>window.removeEventListener('resize',resized))
let geoTimer:ReturnType<typeof setInterval>;onMounted(()=>{void pollGeo(true);geoTimer=setInterval(()=>void pollGeo(),2500)});onUnmounted(()=>clearInterval(geoTimer))
watch(()=>state.data.nodes.map(n=>n.server).join('|'),()=>void pollGeo(true))
const message=useMessage(),dialog=useDialog(),query=ref(''),status=ref('all'),protocol=ref('reality'),page=ref(1),pageSize=ref(20),checked=ref<string[]>([]),sort=ref({key:'name',order:'ascend'})
try{const v=Number(localStorage.getItem('relay-page-size'));if([20,50,100].includes(v))pageSize.value=v}catch{}
const protocolOptions=computed(()=>[...state.data.protocols,...(state.data.protocols.length>1?['all']:[])].map(p=>({value:p,label:protocolNames[p]})))
watch(()=>state.data.protocols,ps=>{if(protocol.value!=='all'&&!ps.includes(protocol.value))protocol.value=ps[0]||'reality'},{immediate:true})
watch([query,status,protocol,pageSize],()=>{page.value=1;try{localStorage.setItem('relay-page-size',String(pageSize.value))}catch{}})
const filtered=computed(()=>filterNodes(state.data.nodes,query.value,status.value,query.value.trim()?state.locations:undefined));const sorted=computed(()=>[...filtered.value].sort((a,b)=>{const key=sort.value.key,get=(n:RelayNode):any=>key==='name'?nameOf(n,protocol.value):key==='protocol'?protocolNames[protocol.value]:key==='location'?state.locations[n.server]?.label||'':key==='port'?(n.ports[protocol.value]||n.port):key==='latency'?state.latency.results[n.id]?.ms??null:key==='rate'?sum(state.traffic.rates?.[n.traffic_id||n.id]):key==='total'?sum(state.traffic.totals?.[n.traffic_id||n.id]):key==='enabled'?Number(n.enabled):n.server;const x=get(a),y=get(b);if(x===null||y===null)return x===y?0:x===null?1:-1;return (typeof x==='number'?x-y:String(x).localeCompare(String(y),'zh-CN',{numeric:true}))*(sort.value.order==='descend'?-1:1)}))
const pageNodes=computed(()=>sorted.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value));watch(()=>sorted.value.length,n=>{page.value=Math.min(page.value,Math.max(1,Math.ceil(n/pageSize.value)))})
function sum(v:any){return (v?.download||0)+(v?.upload||0)}
function selection(keys:Array<string|number>){const visible=new Set(pageNodes.value.map(n=>n.id));checked.value=[...new Set([...checked.value.filter(id=>!visible.has(id)),...keys.map(String)])]}
function action(icon:any,label:string,fn:()=>unknown){return h(NButton,{quaternary:true,size:'small','aria-label':label,title:label,onClick:fn},{icon:()=>h(icon,{size:16})})}
async function run(fn:()=>Promise<unknown>,ok?:string){try{await fn();if(ok)message.success(ok)}catch(e){message.error((e as Error).message)}}
const qr=ref(false),qrTitle=ref(''),qrLinks=ref<Record<string,string>>({})
function showQr(n:RelayNode){qrTitle.value=nameOf(n,protocol.value);qrLinks.value=n.links;qr.value=true}
function subscription(){return (state.data.subscription_base||location.origin)+state.data.subscription_path}
function subQr(){qrTitle.value='订阅';qrLinks.value=Object.fromEntries(protocolOptions.value.map(p=>[p.value,subscription()+'?protocol='+p.value]));qr.value=true}
const columns=computed<DataTableColumns<RelayNode>>(()=>[
 {type:'selection',width:40},
 {title:'节点名称',key:'name',width:210,sorter:true,sortOrder:sort.value.key==='name'?sort.value.order as any:false,ellipsis:{tooltip:true},render:(n:RelayNode)=>h('span',{class:'node-name'},nameOf(n,protocol.value))},
 {title:'入口协议',key:'protocol',width:105,sorter:true,render:()=>h(NTag,{size:'small',bordered:false,type:'info'},()=>protocol.value==='all'?'多协议':protocolNames[protocol.value])},
 {title:'当前落地',key:'server',width:150,sorter:true,render:(n:RelayNode)=>h('span',{class:'mono'},n.server+':'+n.socks_port)},
 {title:'落地国家 / 地区',key:'location',width:175,sorter:true,render:(n:RelayNode)=>h(GeoCell,{host:n.server})},
 {title:'入口端口',key:'port',width:80,sorter:true,render:(n:RelayNode)=>protocol.value==='all'?Object.values(n.ports).join(' / '):(n.ports[protocol.value]||n.port)+(n.shared_batch?' · 共用':'')},
 {title:'落地延迟',key:'latency',width:90,sorter:true,render:(n:RelayNode)=>h(LatencyCell,{id:n.id,test:(ids:string[])=>run(()=>testLatency(ids))})},
 ...(['rate','total'] as const).map(type=>({title:type==='rate'?'实时速率 ↓ / ↑':'累计流量 ↓ / ↑',key:type,width:125,sorter:true,render:(n:RelayNode)=>h(FlowCell,{id:n.traffic_id||n.id,kind:type,shared:!!n.shared_batch})})),
 {title:'操作',key:'actions',width:144,fixed:'right',render:(n:RelayNode)=>h('div',{class:'row-actions'},[action(Pencil,'更换落地 '+n.name,()=>openEdit(n)),action(Copy,'复制节点 '+n.name,()=>run(()=>copy(linksOf(n,protocol.value).join('\n')),'已复制')),action(QrCode,'二维码 '+n.name,()=>showQr(n)),h(NSwitch,{size:'small',value:n.enabled,'aria-label':(n.enabled?'停用 ':'启用 ')+n.name,onUpdateValue:()=>dialog.warning({title:n.enabled?'停用线路':'启用线路',content:'应用会重新加载托管线路，已有连接可能短暂中断。',positiveText:'确认',negativeText:'取消',onPositiveClick:()=>run(async()=>{await api('/api/toggle',{id:n.id});await refresh()},'线路状态已更新')})})])}
].map(c=>('sorter' in c?{...c,sortOrder:sort.value.key===c.key?sort.value.order:false}:c)) as DataTableColumns<RelayNode>)
function sortUpdate(v:any){sort.value=v?{key:v.columnKey,order:v.order||'ascend'}:{key:'name',order:'ascend'};page.value=1}
const exportOpen=ref(false),exportProtocols=ref<string[]>([]),exportScope=ref('enabled')
const exportProtocolOptions=computed(()=>state.data.protocols.map(p=>({value:p,label:protocolNames[p]||p})))
const exportScopeOptions=computed(()=>[{label:`当前筛选中已启用的节点（${filtered.value.filter(n=>n.enabled).length} 条）`,value:'enabled'},{label:`当前筛选的全部节点（${filtered.value.length} 条）`,value:'filtered'},...(checked.value.length?[{label:`已勾选的节点（${checked.value.length} 条）`,value:'selected'}]:[])])
const exportList=computed(()=>exportScope.value==='selected'?state.data.nodes.filter(n=>checked.value.includes(n.id)):filtered.value.filter(n=>exportScope.value==='filtered'||n.enabled))
const exportLinks=computed(()=>exportList.value.flatMap(n=>exportProtocols.value.filter(p=>state.data.protocols.includes(p)).flatMap(p=>linksOf(n,p))))
function openExport(){exportProtocols.value=protocol.value==='all'?[...state.data.protocols]:[protocol.value];exportScope.value=checked.value.length?'selected':'enabled';exportOpen.value=true}
function exportNodes(){if(!exportLinks.value.length)return message.warning('没有可导出的节点链接');download(exportLinks.value.join('\n')+'\n','relay-'+exportProtocols.value.join('-')+'.txt');exportOpen.value=false;message.success(`已导出 ${exportLinks.value.length} 条链接`)}
const portMode=ref('individual');watch(portMode,()=>{guard.invalidate();preview.value=null;previewText.value=''})
const add=ref(false),bulk=ref(''),preview=ref<any>(null),previewText=ref(''),previewBusy=ref(false),saving=ref(false),guard=createPreviewGuard()
watch(bulk,()=>{guard.invalidate();preview.value=null;previewText.value=''},{flush:'sync'})
async function previewAdd(){const version=guard.capture(),text=bulk.value;previewBusy.value=true;try{const result=await api('/api/preview',{text,port_mode:portMode.value});if(!guard.valid(version)||bulk.value!==text)return;preview.value=result;previewText.value=text}catch(e){if(guard.valid(version))message.error((e as Error).message)}finally{previewBusy.value=false}}
async function applyAdd(){if(!preview.value?.added||previewText.value!==bulk.value||saving.value)return;saving.value=true;try{const r=await api('/api/add',{text:bulk.value,port_mode:portMode.value});bulk.value='';add.value=false;await refresh();message.success(`已添加 ${r.added} 条线路`)}catch(e){message.error((e as Error).message)}finally{saving.value=false}}
const edit=ref(false),form=ref<any>({})
async function openEdit(n:RelayNode){await run(async()=>{const v=await api('/api/node?id='+encodeURIComponent(n.id));form.value={id:n.id,name:v.auto_name?'':v.name,server:v.server,socks_port:v.socks_port,username:v.username,password:'',clear_password:false,has_password:v.has_password};edit.value=true})}
async function saveEdit(){if(saving.value)return;saving.value=true;try{await api('/api/edit',form.value);edit.value=false;form.value.password='';await refresh();message.success('落地已更新，入口链接保持不变')}catch(e){message.error((e as Error).message)}finally{saving.value=false}}
watch(edit,v=>{if(!v)form.value.password=''});watch(add,v=>{if(!v){bulk.value='';preview.value=null}})
</script>
<template>
 <div class="page-heading"><div><div class="eyebrow">CONNECTIONS</div><h1>节点管理 <span class="heading-count">{{state.data.nodes.length}}</span></h1><p>{{state.data.public_host}}</p></div><NSpace><NButton @click="run(()=>copy(subscription()+'?protocol='+protocol),'已复制订阅')"><template #icon><Link :size="16"/></template>复制订阅</NButton><NButton aria-label="订阅二维码" @click="subQr"><template #icon><QrCode :size="17"/></template></NButton><NButton type="primary" @click="add=true"><template #icon><Plus :size="17"/></template>添加节点</NButton></NSpace></div>
 <NodeMetrics/>
 <section class="panel node-panel"><div class="table-toolbar"><NInput v-model:value="query" clearable placeholder="搜索名称、IP、地区、端口" aria-label="搜索节点" class="search"><template #prefix><Search :size="16"/></template></NInput><div class="filter-actions"><NSelect v-model:value="protocol" :options="protocolOptions" class="protocol-select" aria-label="选择节点协议"/><NSelect v-model:value="status" :options="[{label:'全部状态',value:'all'},{label:'已启用',value:'enabled'},{label:'已停用',value:'disabled'}]" class="status-select" aria-label="筛选节点状态"/><NButton :loading="state.latency.running" @click="run(()=>testLatency(checked.length?checked:filtered.map(n=>n.id)))">{{checked.length?'测试选中 '+checked.length:'测试延迟'}}</NButton><NButton @click="openExport"><template #icon><Download :size="16"/></template>{{checked.length?'导出选中':'导出节点'}}</NButton><NButton aria-label="刷新节点" @click="run(refresh)"><template #icon><RefreshCw :size="16"/></template></NButton></div></div>
 <NDataTable :columns="columns" :data="pageNodes" :row-key="(n:RelayNode)=>n.id" :checked-row-keys="checked" @update:checked-row-keys="selection" @update:sorter="sortUpdate" :scroll-x="1344" :max-height="Math.max(240,viewport-385)" size="small" :bordered="false" :single-line="true" :virtual-scroll="true"/>
 <div class="table-footer"><span class="muted">共 {{filtered.length}} 条 <span v-if="checked.length">· 已选 {{checked.length}} 条</span><span v-if="state.latency.total"> · {{state.latency.running?'测试中':'已完成'}} {{state.latency.completed}}/{{state.latency.total}}</span></span><NPagination v-model:page="page" v-model:page-size="pageSize" :item-count="filtered.length" :page-sizes="[20,50,100]" show-size-picker :page-slot="5"/></div></section>
 <NModal v-model:show="exportOpen" preset="card" title="导出节点" class="dialog"><NForm label-placement="top"><NFormItem label="导出协议"><NSelect v-model:value="exportProtocols" multiple :options="exportProtocolOptions" placeholder="选择一个或多个协议" aria-label="导出协议"/></NFormItem><NFormItem label="导出范围"><NSelect v-model:value="exportScope" :options="exportScopeOptions" aria-label="导出范围"/></NFormItem></NForm><p class="muted">共 {{exportList.length}} 个节点 · {{exportLinks.length}} 条链接</p><template #footer><NSpace justify="end"><NButton @click="exportOpen=false">取消</NButton><NButton type="primary" :disabled="!exportLinks.length" @click="exportNodes"><template #icon><Download :size="16"/></template>导出 TXT</NButton></NSpace></template></NModal>
 <NModal v-model:show="add" preset="card" title="批量添加 SOCKS5" class="dialog" :mask-closable="!saving" :close-on-esc="!saving" :closable="!saving"><NFormItem label="入口端口模式"><NSelect v-model:value="portMode" :disabled="saving" :options="[{label:'独立端口 · 每条线路独立统计',value:'individual'},{label:'批次共用端口 · 按批次统计',value:'shared',disabled:state.data.protocols.includes('shadowsocks')}]" aria-label="入口端口模式"/></NFormItem><p v-if="portMode==='shared'" class="info-strip">本次新增节点组成一个批次，每种协议共用一个端口，按独立认证身份分配落地；流量显示批次合计。</p><NInput v-model:value="bulk" type="textarea" :disabled="saving" :autosize="{minRows:7,maxRows:12}" placeholder="地址|端口|账号|密码|名称&#10;每行一条，名称留空自动生成" aria-label="落地节点"/><div v-if="preview" class="preview-list"><p>新增 {{preview.added}} 条 · 跳过重复 {{preview.skipped}} 条</p><div v-for="n in preview.nodes" :key="n.port">{{n.name}} → {{n.port}}</div></div><NAlert type="warning" :show-icon="false" class="form-note">应用会重新加载托管线路，已有连接可能短暂中断。</NAlert><template #footer><NSpace justify="end"><NButton :loading="previewBusy" :disabled="saving" @click="previewAdd">预览节点</NButton><NButton type="primary" :loading="saving" :disabled="!preview?.added||previewText!==bulk" @click="applyAdd">添加并生成</NButton></NSpace></template></NModal>
 <NModal v-model:show="edit" preset="card" title="更换落地" class="dialog" :mask-closable="!saving" :closable="!saving"><NForm label-placement="top" @submit.prevent="saveEdit"><NFormItem label="节点名称"><NInput v-model:value="form.name" placeholder="留空使用落地 IP + 协议"/></NFormItem><div class="form-grid"><NFormItem label="落地地址"><NInput v-model:value="form.server"/></NFormItem><NFormItem label="SOCKS5 端口"><NInputNumber v-model:value="form.socks_port" :min="1" :max="65535"/></NFormItem></div><NFormItem label="账号"><NInput v-model:value="form.username" autocomplete="off"/></NFormItem><NFormItem label="密码"><NInput v-model:value="form.password" type="password" show-password-on="click" :placeholder="form.has_password?'留空保留现有密码':'可留空'" autocomplete="new-password"/></NFormItem><NCheckbox v-model:checked="form.clear_password">清除原密码</NCheckbox></NForm><template #footer><NSpace justify="end"><NButton :disabled="saving" @click="edit=false">取消</NButton><NButton type="primary" :loading="saving" @click="saveEdit">保存落地</NButton></NSpace></template></NModal>
 <QrDialog v-model:show="qr" :title="qrTitle" :links="qrLinks" :initial="protocol"/>
</template>

